let gridStep=20,axisPreview=null;
function updateWorld(){let bg=$('#gridbg'),r=svg.getBoundingClientRect();bg.setAttribute('x',camera.x);bg.setAttribute('y',camera.y);bg.setAttribute('width',camera.w);bg.setAttribute('height',camera.h);let desired=camera.w/Math.max(1,r.width)*24,power=10**Math.floor(Math.log10(desired));gridStep=[1,2,5,10].map(n=>n*power).find(n=>n>=desired)||power*10;let defs=svg.querySelector('defs'),pattern=$('#worldGrid');if(!pattern){pattern=node('pattern',{id:'worldGrid',patternUnits:'userSpaceOnUse'});defs.append(pattern)}pattern.setAttribute('width',gridStep*5);pattern.setAttribute('height',gridStep*5);let scale=camera.w/Math.max(1,r.width);pattern.replaceChildren();for(let i=0;i<5;i++)pattern.append(node('path',{d:`M ${i*gridStep} 0 V ${gridStep*5} M 0 ${i*gridStep} H ${gridStep*5}`,stroke:i===0?'#b9cdc3':'#dce7e0','stroke-width':scale*(i===0?.8:.5),fill:'none'}));bg.setAttribute('fill','url(#worldGrid)');bg.style.display=data.grid?'':'none';for(let g of $('#objects').children){let o=items().find(o=>o.id===g.dataset.id);if(o?.type.endsWith('axis'))stretchAxis(g,o)}let c=$('#mapcoords');if(c)c.textContent=`网格 ${gridStep} px · 无限画布`}
