const worldProps=props;props=function(){worldProps();$('#properties').querySelectorAll('input[type=number]').forEach(n=>{n.removeAttribute('max');if(n.dataset.k==='x'||n.dataset.k==='y')n.removeAttribute('min')});if(!sel()){let help=$('#properties .emptyprop');if(help)help.innerHTML='滚轮以鼠标位置缩放，空格或中键拖动平移。<br><br>画布没有边界，可向任意方向绘制。网格随缩放自动调整密度。<br><br>轴线：点击即可放置，自动连续编号。使用「轴网」一次生成整组横纵轴线。'}};
