svg.addEventListener('pointermove',e=>{let p=rawPoint(e);$('#mapcoords').textContent=`X ${Math.round(p.x)} · Y ${Math.round(p.y)} · 网格 ${gridStep} px`;if(drag||spaceHeld||!tool.endsWith('axis')){clearPreview();return}let a=smartAxis(e),draft=axisDraft(tool,a),scale=camera.w/svg.getBoundingClientRect().width;if(!axisPreview){axisPreview=node('g',{'pointer-events':'none'});svg.append(axisPreview)}axisPreview.replaceChildren(node('line',{x1:draft.x1,y1:draft.y1,x2:draft.x2,y2:draft.y2,stroke:'#26966b','stroke-dasharray':'6 4','vector-effect':'non-scaling-stroke'}),node('text',{x:p.x+14*scale,y:p.y-14*scale,fill:'#16774e','font-size':12*scale},`${nextName(tool)} · ${a.reference?`参考 ${a.reference} / ${a.spacing} m · `:''}${Math.round(a.value*100)/100} m · 长 ${draft.length} m　点击放置`))});
