svg.addEventListener('pointerdown',e=>{if(e.button!==0||spaceHeld||!tool.endsWith('axis'))return;e.stopImmediatePropagation();e.preventDefault();let a=smartAxis(e),existing=items().find(o=>o.type===tool&&Math.abs((a.h?o.y:o.x)-a.value)<.000001);if(existing){selected=existing.id;draw();props();toast('该位置已有轴线，请调小轴距后插入，或按 Alt 自由定位');return}checkpoint();let draft=axisDraft(tool,a),o=obj(tool,nextName(tool),draft.x,draft.y,draft.w,draft.h);items().push(o);if(typeof alignAxisGroup==='function'){alignAxisGroup(tool);alignAxisGroup(tool==='haxis'?'vaxis':'haxis')}selected=o.id;clearPreview();save();render()},true);
let axisDialog=document.createElement('dialog');axisDialog.id='axisdialog';axisDialog.innerHTML=`<form method="dialog"><div class="dialoghead"><div><div class="eyebrow">AXIS GRID</div><h2>一键生成轴网</h2></div><button value="cancel" aria-label="关闭">×</button></div><p>横轴按 A、B、C 编号，纵轴按 1、2、3 编号。已有同位置轴线会自动跳过。</p><div class="axisform"><fieldset><legend>横向轴线</legend><label>数量<input id="hcount" type="number" value="4" min="0" max="100"></label><label>间距（px）<input id="hgap" type="number" value="200" min="0.01" step="0.01"></label></fieldset><fieldset><legend>纵向轴线</legend><label>数量<input id="vcount" type="number" value="5" min="0" max="100"></label><label>间距（px）<input id="vgap" type="number" value="200" min="0.01" step="0.01"></label></fieldset><fieldset class="origin"><legend>第一根轴线交点</legend><label>X 坐标<input id="originx" type="number" value="0"></label><label>Y 坐标<input id="originy" type="number" value="0"></label></fieldset></div><div id="axisestimate"></div><div class="dialogactions"><button value="cancel">取消</button><button type="button" id="generateaxes">生成轴网</button></div></form>`;document.body.append(axisDialog);
function axisEstimate(){let h=Number($('#hcount').value),v=Number($('#vcount').value),hg=Number($('#hgap').value),vg=Number($('#vgap').value);$('#axisestimate').textContent=`${h} 根横轴 + ${v} 根纵轴 · 跨度 ${Math.max(0,v-1)*vg} × ${Math.max(0,h-1)*hg} px`}
axisDialog.querySelectorAll('input').forEach(n=>n.oninput=axisEstimate);
function openAxes(){clearPreview();$('#originx').value=Math.round((camera.x+camera.w*.2)/20)*20;$('#originy').value=Math.round((camera.y+camera.h*.2)/20)*20;axisEstimate();axisDialog.showModal()}
$('#generateaxes').onclick=()=>{let form=axisDialog.querySelector('form');if(!form.reportValidity())return;let h=Number($('#hcount').value),v=Number($('#vcount').value),hg=Number($('#hgap').value),vg=Number($('#vgap').value),x=Number($('#originx').value),y=Number($('#originy').value);if(![h,v,hg,vg,x,y].every(Number.isFinite)||!Number.isInteger(h)||!Number.isInteger(v)||h+v===0){toast('请填写有效的轴线数量与间距');return}checkpoint();let added=0;for(let [t,count,gap]of[['haxis',h,hg],['vaxis',v,vg]])for(let i=0;i<count;i++){let pos=(t==='haxis'?y:x)+gap*i;if(items().some(o=>o.type===t&&Math.abs((t==='haxis'?o.y:o.x)-pos)<.000001))continue;const length=configuredAxisLength(t);items().push(obj(t,nextName(t),t==='haxis'?x:pos,t==='haxis'?pos:y,t==='haxis'?length:0,t==='vaxis'?length:0));added++}if(typeof alignAxisGroup==='function'){alignAxisGroup('haxis');alignAxisGroup('vaxis')}data.axes=true;if(page){data.planSettings??={};data.planSettings[planKey()]??={};data.planSettings[planKey()].axes=true}selected=null;tool='select';save();axisDialog.close();render();fitCanvas();toast(`已生成 ${added} 根轴线`)};
